CREATE OR REPLACE FUNCTION public.jobs_daily_summary() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $function$ INSERT INTO public.job_operational_summaries(day,live,expired,source_failures,open_reports) SELECT current_date,(SELECT count(*) FROM public.jobs WHERE verification_status='VERIFIED' AND application_status='OPEN' AND source_access_status='AUTHORIZED' AND NOT admin_hold AND is_primary AND original_posted_at>now()-interval '7 days' AND original_posted_at<=now() AND expires_at>now() AND last_verified_at>now()-interval '12 hours' AND last_application_checked_at>now()-interval '12 hours' AND verification_basis='authorized_feed_and_live_link'),(SELECT count(*) FROM public.jobs WHERE expires_at>=current_date AND expires_at<current_date+interval '1 day'),(SELECT count(*) FROM public.job_sources WHERE last_error IS NOT NULL),(SELECT count(*) FROM public.reported_jobs WHERE status='open') ON CONFLICT(day) DO UPDATE SET live=excluded.live,expired=excluded.expired,source_failures=excluded.source_failures,open_reports=excluded.open_reports; $function$;
REVOKE ALL ON FUNCTION public.jobs_daily_summary() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.jobs_daily_summary() TO service_role;